import { writeFileSync, readFileSync } from "node:fs";
import { designTokens } from "../src/design-system/tokens.ts";
const file = new URL("../src/design-system/tokens.css", import.meta.url);
const css =
  "/* Generated by scripts/generate-design-tokens.mjs; edit tokens.ts. */\n:root {\n" +
  Object.entries(designTokens)
    .map(([key, value]) => `  ${key}: ${value};\n`)
    .join("") +
  "}\n";
if (process.argv.includes("--check")) {
  if (readFileSync(file, "utf8").replaceAll("\r\n", "\n") !== css)
    throw new Error("Run npm run tokens to update tokens.css");
} else writeFileSync(file, css);
